{"cards": [{"node_code": "N_5f25c87d9ea7862c", "definition": "涵盖用于农田灌溉、城市排水及水利调度的提水设备、输水管道系统、喷灌滴灌装置及排水泵站等机械装备。", "boundary": "聚焦于水资源的提升、输送、分配及排除过程中的机械系统。与“河道、堤坝与水利施工机械”的区别在于本节点侧重运行期的水循环管理，而非建设期的土建施工；与“热流体与能源动力工程”的区别在于本节点侧重农业/水利场景下的系统配置与应用，而非泵类通用流体力学原理。", "includes": ["各类农业水泵、喷灌机、滴灌系统及微灌设备", "农田排水机械、城市雨水/污水提升泵站", "长距离输水管道阀门及水力控制设备"], "excludes": ["工业循环水冷却系统（归入过程工业或热流体工程）", "泵类通用的水力模型、叶轮设计理论（归入热流体与能源动力工程）"], "sibling_distinctions": [{"other_code": "N_4bff4950ceeb5438", "rule": "本节点收录用于日常灌溉、排水及调度的运行设备；兄弟节点收录用于河道疏浚、堤坝建设及维护的施工机械。"}, {"other_code": "N_cf48269af6ce3f44", "rule": "本节点收录水体管理与输送机械；兄弟节点收录针对水生生物（鱼虾等）的捕捞、养殖及加工设备。"}], "cross_boundary_rule": "涉及水泵时，若研究其在特定农田或水利系统中的选型、布局及运行管理，主挂载至本节点；若研究泵本身的通用效率、水力结构或材料特性，主挂载至“热流体与能源动力工程”。"}, {"node_code": "N_4bff4950ceeb5438", "definition": "涵盖用于河道治理、堤防建设、水库维护及水利枢纽施工专用的机械装备，包括疏浚船、打桩机及土方作业设备。", "boundary": "聚焦于水利基础设施的建设、改造与维护过程中的机械作业。与“提水、灌溉与排水机械”的区别在于本节点侧重工程实施阶段（如挖泥、筑堤），而非运行阶段的水资源调度；与“工程机械”的区别在于本节点特指服务于水利场景的专用或适配设备，而非通用建筑机械。", "includes": ["河道疏浚船、挖泥船及清淤设备", "堤坝打桩机、护坡施工机械及土工布铺设设备", "水库大坝检测、加固及应急抢险专用机械"], "excludes": ["大坝、水闸等水利枢纽的混凝土结构设计与施工方法（归入土木工程）", "通用挖掘机、装载机等非水利专用的通用工程机械（归入工程机械与矿山机械）"], "sibling_distinctions": [{"other_code": "N_5f25c87d9ea7862c", "rule": "本节点收录水利工程建设与维护阶段的施工机械；兄弟节点收录水利设施建成后的运行管理设备（如水泵、阀门）。"}, {"other_code": "N_cf48269af6ce3f44", "rule": "本节点收录水体环境改造与工程设施施工机械；兄弟节点收录水生生物资源开发与加工机械。"}], "cross_boundary_rule": "涉及疏浚或土方机械时，若研究其在河道、堤坝等特定水利场景下的作业工艺、专用配置或工程规范，主挂载至本节点；若研究机械本身的通用动力学、结构强度或通用操作技术，主挂载至“工程机械与矿山机械”。"}, {"node_code": "N_cf48269af6ce3f44", "definition": "涵盖水产养殖、捕捞作业及水产品初加工领域的专用机械装备，包括渔船、网具、增氧设备及冷链处理设施。", "boundary": "聚焦于水生生物资源的获取、培育及初步处理。与“提水、灌溉与排水机械”的区别在于作业对象为生物体而非水体本身；与“轻工、食品与纺织机械”的区别在于本节点侧重捕捞、养殖及初加工（如去鳞、冷冻），而非工厂内的精深加工生产线。", "includes": ["各类渔船、拖网、围网及捕捞辅助机械", "水产养殖增氧机、投饵机、水质监测及循环水系统", "水产品去鳞、去内脏、冷冻、冷藏及初包装设备"], "excludes": ["水产品精深加工生产线（如罐头、鱼糜制品）（归入轻工、食品与纺织机械）", "海洋工程平台、海底电缆铺设等非渔业专用的海洋工程装备（归入船舶与海洋工程或过程工业）"], "sibling_distinctions": [{"other_code": "N_5f25c87d9ea7862c", "rule": "本节点收录针对水生生物的作业与处理机械；兄弟节点收录针对水体输送、灌溉与排水的机械。"}, {"other_code": "N_4bff4950ceeb5438", "rule": "本节点收录渔业生产与加工机械；兄弟节点收录水利工程建设与维护施工机械。"}], "cross_boundary_rule": "涉及水产品加工时，若为捕捞后的初加工（如清洗、分割、冷冻）或养殖环节的设备，主挂载至本节点；若为工厂内的精深加工（如油炸、调味、罐头封装），主挂载至“轻工、食品与纺织机械”。"}]}
